  if (/^\d{3}-\d{7}-\d{7}$/.test(trimmed)) return false;
  if (trimmed.length < 8 || trimmed.length > 40) return false;
  if (!/\d/.test(trimmed)) return false;
  if (!/^[A-Za-z0-9-]+$/.test(trimmed)) return false;
  return true;
}

